const READS = new Set(['ping', 'ready', 'list', 'beliefs', 'read'])

// ── edit-location errors (gap 3 at scale): an Edit the tool refused, by why ──
const editFailures = { not_unique: 0, not_found: 0, stale: 0, other: 0 }
