  const cands = lastEdge ? [...(lastEdge.red || [])] : []
  if (lastEdge && W.check && lastEdge.check !== 0) cands.push({ task: 'check', cmd: W.check.join(' '), exit: lastEdge.check, tail: lastEdge.checkTail || '' })
  let size = Buffer.byteLength(JSON.stringify(rec))
