function byOp (ops) {
  const g = {}
  for (const o of ops) (g[o.name] = g[o.name] || []).push(o.us)
  return Object.fromEntries(Object.entries(g).map(([k, xs]) => [k, { n: xs.length, p50_us: pct(xs, 0.5), p90_us: pct(xs, 0.9), max_us: pct(xs, 1) }]))
